import XCTest
import KwipMLCore
@testable import KwipMLApp

final class WorkflowObjectiveIdentityTests: XCTestCase {
    private func fixture(_ task:LossLearningTask)throws->([String:JSONValue],WorkflowExecutionPlan,PreparedObjectiveSelection,ComponentRegistry) {
        let registry=try ComponentRegistry.builtIn()
        let repo=URL(fileURLWithPath:#filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let data=try DataFlowOperatorRegistry.load(from:repo.appendingPathComponent("runner/dataflow-operators.json"))
        let plan=try WorkflowCompiler.compile(WorkflowExamples.preparedLossObjective(task:task,device:"cpu"),train:WorkflowExamples.trainAddress,modelRegistry:registry,dataRegistry:data,contractVersion:13)
        let m=try JSONDecoder().decode([String:JSONValue].self,from:Data(Self.manifests[task.componentID]!.utf8))
        guard case .object(let provenance)=m["provenance"],case .object(let prepared)=provenance["preparation"] else {throw WorkflowPhaseError("Fixture lacks genuine preparation")}
        let recipe=try XCTUnwrap(plan.lossRecipe)
        let reference=PreparedDataReference(manifestPath:"/prepared/manifest.json",manifestSHA256:prepared["manifestSHA256"]!.stringValue!,graphDigest:prepared["graphDigest"]!.stringValue!,trainingNode:prepared["trainingNode"]!.stringValue!,trainingPort:prepared["trainingPort"]!.stringValue!,validationNode:prepared["validationNode"]!.stringValue!,validationPort:prepared["validationPort"]!.stringValue!)
        return(m,plan,.init(reference:reference,objectiveRecipe:recipe.configuration.recipeValue,targetMapping:recipe.targetMapping,scalarization:plan.objectiveScalarization),registry)
    }
    private func verify(_ m:[String:JSONValue],_ plan:WorkflowExecutionPlan,_ selection:PreparedObjectiveSelection,_ registry:ComponentRegistry)throws->WorkflowObjectiveArtifactContext {
        try WorkflowObjectiveIdentity.validate(m,selection:selection,recipe:XCTUnwrap(plan.lossRecipe),inputContract:WorkflowMappingRequirements.inputContract(plan.model.graph,registry:registry,context:.explicitObjective),outputContract:WorkflowMappingRequirements.outputContract(plan.model.graph,registry:registry),expectedEpochs:3,policy:.factory)
    }
    func testAllEightActualCPUManifestsBindExactPreparedObjectiveAndGeometry()throws {
        for task in LossLearningTask.allCases {
            let(m,plan,selection,registry)=try fixture(task)
            do {
                let context=try verify(m,plan,selection,registry)
                XCTAssertEqual(context.recipe,plan.lossRecipe);XCTAssertEqual(context.trainingCount,48);XCTAssertEqual(context.evaluationCount,16)
                XCTAssertEqual(context.inputContract.layout.sample.dimensions,task == .triplet ? [6]:[2])
                XCTAssertEqual(context.outputSampleShape,try WorkflowMappingRequirements.outputContract(plan.model.graph,registry:registry).layout.sample.dimensions)
                XCTAssertEqual(context.device,.cpu)
            } catch {XCTFail("\(task.rawValue): \(error)")}
        }
    }
    func testEveryIdentityLocationRejectsChangedOrMissingCapturedControlsAndRoles()throws {
        let paths:[[String]]=[["settings","objectiveRecipe"],["provenance","objectiveRecipe"],["provenance","objective","recipe"],["checkpoint","contract","objective","recipe"],["settings","targetMapping"],["provenance","objectiveMapping"],["provenance","objective","targetMapping"],["checkpoint","contract","objective","targetMapping"],["settings","objectiveScalarization"],["provenance","objective","scalarization"],["checkpoint","contract","objective","scalarization"],["provenance","preparation","manifestSHA256"],["provenance","preparation","trainingPort"],["provenance","modelInput","columnOrder"],["provenance","modelInput","sampleShape"],["provenance","objective","torchVersion"],["provenance","trainingSamples"],["runtime","device"]]
        for task in LossLearningTask.allCases {
            let(m,plan,selection,registry)=try fixture(task)
            for path in paths {
                let changed=Self.changed(m,path:path,value:.null)
                XCTAssertThrowsError(try verify(changed,plan,selection,registry),"\(task.rawValue) \(path)")
            }
            let legacy=Self.changed(m,path:["provenance","targetColumn"],value:.string("invented binary target"))
            XCTAssertThrowsError(try verify(legacy,plan,selection,registry))
            var other=selection;other.scalarization = .sum
            XCTAssertThrowsError(try verify(m,plan,other,registry))
        }
    }
    func testIncompleteRecipeCannotAcquireImplicitDefaultsAndUnknownIdentityFieldsAreRefused()throws {
        let(m,plan,selection,registry)=try fixture(.mse)
        let paths=[["settings","objectiveRecipe","config","target_broadcast"],["provenance","objective","unexpected"],["checkpoint","contract","objective","unexpected"]]
        for path in paths {XCTAssertThrowsError(try verify(Self.changed(m,path:path,value:.null),plan,selection,registry))}
    }
    func testCheckpointRuntimeCannotContradictActualObjectiveDeviceOrTorch()throws {
        for task in LossLearningTask.allCases {
            let(m,plan,selection,registry)=try fixture(task)
            for path in [["checkpoint","contract","runtime","device"],["checkpoint","contract","runtime","torch"]] {
                XCTAssertThrowsError(try verify(Self.changed(m,path:path,value:.string("contradictory")),plan,selection,registry),"\(task.rawValue) \(path)")
            }
        }
    }
    private static func changed(_ root:[String:JSONValue],path:[String],value:JSONValue)->[String:JSONValue] {
        var result=root
        if path.count == 1 {result[path[0]]=value}
        else if case .object(let child)=result[path[0]] {result[path[0]] = .object(changed(child,path:Array(path.dropFirst()),value:value))}
        return result
    }
